    ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px2, py2); ctx.stroke();
  }
  // eyes in the dark
  ctx.globalCompositeOperation = 'lighter';
  const blink = Math.max(0.12, Math.abs(Math.sin(t * 0.7 - 1.2)));
  for (let i = 0; i < 3; i++) {
