    ctx.globalAlpha = blink * (0.5 + Math.sin(t * 2 + i) * 0.2);
    drawGlow(ctx, '#ff3d26', ex, ey, 20, 0.9);
    ctx.fillStyle = '#ff6a4a';
    ctx.beginPath(); ctx.arc(ex - 5, ey, 1.8, 0, TAU); ctx.fill();
    ctx.beginPath(); ctx.arc(ex + 5, ey, 1.8, 0, TAU); ctx.fill();
  }
