    if (has('athena_step')) dashCd *= 1 - clamp(v('athena_step', 12) * 0.8, 0, 60) / 100;
    if (has('hermes_speed')) dashCd *= 1 - clamp(v('hermes_speed', 12) * 1.3, 0, 60) / 100;
