// Enemy and boss behaviour, death resolution.
import { TAU, clamp, damp, rnd, chance, pick, dist, angleTo, angleDiff, approachAngle, norm } from './core.js';
import { ENEMY_TYPES } from './data.js';
import { ROOM_W, ROOM_H, MARGIN } from './constants.js';

export const aiMethods = {
  updateEnemies(dt) {
    const p = this.player;
    for (const e of this.enemies) {
      if (e.dead) continue;
      if (e.spawnT > 0) { e.spawnT -= dt; continue; }
      if (e.hurtFlash > 0) e.hurtFlash -= dt;
      if (e.showHp > 0) e.showHp -= dt;

      // poison
      if (e.poison > 0) {
        e.poison -= dt;
        e.poisonTick += dt;
        while (e.poisonTick >= 0.5 && e.poison > 0) {
          e.poisonTick -= 0.5;
          const dmg = (e.poisonDps || 6) * (e.poisonStacks || 1) * 0.5;
          e.hp -= dmg;
          e.showHp = 1.4;
          this.float(e.x + rnd(8, -8), e.y - e.radius * 1.9, Math.round(dmg), 'poison');
          for (let i = 0; i < 2; i++) {
            this.particles.push({
              x: e.x + rnd(10, -10), y: e.y - e.radius * 1.2, vx: rnd(10, -10), vy: rnd(-30, -60),
              t: 0, life: 0.5, kind: 'spark', color: '#b6ff8a', size: 1.6,
            });
          }
          if (e.hp <= 0) { this.killEnemy(e); break; }
        }
      }
      if (e.dead) continue;

      // doom
      if (e.doom > 0) {
        e.doom -= dt;
        if (e.doom <= 0) {
          const dmg = e.doomDmg || 40;
          this.burst(e.x, e.y - e.radius, '#ff5040', 22, 230, 'spark');
          this.ring(e.x, e.y - 10, 110, '#ff5040');
          this.audio.sfx('thunder');
          this.shake(5);
          const others = this.enemies.filter((o) => o !== e && !o.dead && dist(o.x, o.y, e.x, e.y) < 135);
          for (const o of others) this.damageEnemy(o, dmg, { direct: false, raw: true });
          e.hp -= dmg;
          e.showHp = 2;
          this.float(e.x, e.y - e.radius * 2, Math.round(dmg), 'crit');
          if (e.hp <= 0) { this.killEnemy(e); continue; }
        }
      }
      if (e.weaken > 0) e.weaken -= dt;
      if (e.slow > 0) e.slow -= dt;

      const d = dist(e.x, e.y, p.x, p.y) || 1;
      e.face = angleTo(e.x, e.y, p.x, p.y);
      if (e.kind === 'melee') this.aiMelee(e, dt, d);
      else if (e.kind === 'dash') this.aiShade(e, dt, d);
      else if (e.kind === 'ranged') this.aiArcher(e, dt, d);
      else if (e.kind === 'slam') this.aiBrute(e, dt, d);
      else if (e.kind === 'caster') this.aiWitch(e, dt, d);

      e.x = clamp(e.x, MARGIN + e.radius, ROOM_W - MARGIN - e.radius);
      e.y = clamp(e.y, MARGIN + e.radius, ROOM_H - MARGIN - e.radius);
      this.resolveObstacles(e);
    }
    // separation
    for (let i = 0; i < this.enemies.length; i++) {
      const a = this.enemies[i];
      if (a.dead || a.spawnT > 0) continue;
      for (let j = i + 1; j < this.enemies.length; j++) {
        const b = this.enemies[j];
        if (b.dead || b.spawnT > 0) continue;
        const dx = b.x - a.x, dy = b.y - a.y;
        const dd = Math.hypot(dx, dy) || 1;
        const need = (a.radius + b.radius) * 0.92;
        if (dd < need) {
          const push = (need - dd) / dd * 0.5;
          const ma = a.mass || 1, mb = b.mass || 1;
          const wa = mb / (ma + mb), wb = ma / (ma + mb);
          a.x -= dx * push * wa; a.y -= dy * push * wa;
          b.x += dx * push * wb; b.y += dy * push * wb;
        }
      }
    }
    this.enemies = this.enemies.filter((e) => !e.dead);
  },

  resolveObstacles(e) {
    for (const o of this.obstacles) {
      const d = dist(e.x, e.y, o.x, o.y);
      const need = o.r + e.radius * 0.8;
      if (d < need && d > 0.01) {
        const nx = (e.x - o.x) / d, ny = (e.y - o.y) / d;
        e.x = o.x + nx * need;
        e.y = o.y + ny * need;
      }
    }
  },

  enemyMove(e, dx, dy, mult, dt) {
    const slow = e.slow > 0 ? clamp(1 - e.slowAmt, 0.35, 1) : 1;
    const sp = e.speed * mult * slow;
    e.vx = damp(e.vx, dx * sp, 7, dt);
    e.vy = damp(e.vy, dy * sp, 7, dt);
    e.x += (e.vx + e.knockVx) * dt;
    e.y += (e.vy + e.knockVy) * dt;
    e.knockVx *= Math.exp(-7 * dt);
    e.knockVy *= Math.exp(-7 * dt);
    if (Math.hypot(e.vx, e.vy) > 12) e.walkPhase += dt * 9;
  },

  contactDamage(e, range, dmg, angle) {
    const p = this.player;
    if (dist(e.x, e.y, p.x, p.y) < range + p.radius) {
      this.damagePlayer(dmg, angle ?? angleTo(e.x, e.y, p.x, p.y));
      return true;
    }
    return false;
  },

  aiMelee(e, dt, d) {
    e.cooldown -= dt;
    if (e.state === 'windup') {
      e.windup = Math.max(0, e.stateT);
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 10, dt); e.vy = damp(e.vy, 0, 10, dt);
      e.x += e.knockVx * dt; e.y += e.knockVy * dt;
      e.knockVx *= Math.exp(-7 * dt); e.knockVy *= Math.exp(-7 * dt);
      if (e.stateT <= 0) {
        e.state = 'attack'; e.stateT = 0.22; e.attackDir = e.face; e.hitThisAttack = false;
        this.audio.sfx('slash');
      }
      return;
    }
    if (e.state === 'attack') {
      e.stateT -= dt;
      e.x += Math.cos(e.attackDir) * 420 * dt;
      e.y += Math.sin(e.attackDir) * 420 * dt;
      if (!e.hitThisAttack) {
        e.hitThisAttack = this.contactDamage(e, e.radius + 15, e.dmg * (e.weaken > 0 ? 0.6 : 1), e.attackDir);
      }
      if (e.stateT <= 0) { e.state = 'recover'; e.stateT = 0.5; e.cooldown = 1.25 + rnd(0.5); }
      return;
    }
    e.windup = 0;
    if (e.state === 'recover') {
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 8, dt); e.vy = damp(e.vy, 0, 8, dt);
      if (e.stateT <= 0) e.state = 'chase';
      return;
    }
    if (d < e.radius + 48 && e.cooldown <= 0) {
      e.state = 'windup'; e.stateT = 0.52; e.windup = 0.52;
      e.audioPinged = true;
      return;
    }
    if (d > e.radius + 36) this.enemyMove(e, (this.player.x - e.x) / d, (this.player.y - e.y) / d, 1, dt);
    else this.enemyMove(e, 0, 0, 0, dt);
  },

  aiShade(e, dt, d) {
    e.cooldown -= dt;
    if (e.state === 'windup') {
      e.stateT -= dt;
      e.vx = 0; e.vy = 0;
      e.x += e.knockVx * dt; e.y += e.knockVy * dt;
      e.knockVx *= Math.exp(-7 * dt); e.knockVy *= Math.exp(-7 * dt);
      if (e.stateT <= 0) {
        e.state = 'attack'; e.stateT = 0.24; e.attackDir = e.face; e.hitThisAttack = false;
        this.audio.sfx('dash');
      }
      return;
    }
    if (e.state === 'attack') {
      e.stateT -= dt;
      e.x += Math.cos(e.attackDir) * 760 * dt;
      e.y += Math.sin(e.attackDir) * 760 * dt;
      if (!e.hitThisAttack) {
        e.hitThisAttack = this.contactDamage(e, e.radius + 8, e.dmg * (e.weaken > 0 ? 0.6 : 1), e.attackDir);
      }
      if (Math.random() < dt * 30) this.particles.push({ x: e.x, y: e.y - 20, vx: 0, vy: 0, t: 0, life: 0.3, kind: 'spark', color: '#79e8ff', size: 2 });
      if (e.stateT <= 0) { e.state = 'recover'; e.stateT = 0.65; e.cooldown = 1.5 + rnd(0.6); }
      return;
    }
    if (e.state === 'recover') {
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 8, dt); e.vy = damp(e.vy, 0, 8, dt);
      if (e.stateT <= 0) e.state = 'chase';
      return;
    }
    if (d < 210 && e.cooldown <= 0) {
      e.state = 'windup'; e.stateT = 0.42;
      return;
    }
    const perp = Math.sin(this.time * 2 + e.seed) * 0.5;
    const tx = (this.player.x - e.x) / d + -((this.player.y - e.y) / d) * perp;
    const ty = (this.player.y - e.y) / d + ((this.player.x - e.x) / d) * perp;
    this.enemyMove(e, norm(tx, ty).x, norm(tx, ty).y, d > 170 ? 1 : -0.5, dt);
  },

  aiArcher(e, dt, d) {
    e.cooldown -= dt;
    if (e.state === 'windup') {
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 8, dt); e.vy = damp(e.vy, 0, 8, dt);
      e.x += e.knockVx * dt; e.y += e.knockVy * dt;
      e.knockVx *= Math.exp(-7 * dt); e.knockVy *= Math.exp(-7 * dt);
      e.windup = e.stateT;
      if (e.stateT <= 0) {
        e.state = 'recover'; e.stateT = 0.3; e.windup = 0; e.cooldown = 2.0 + rnd(0.8);
        const a = angleTo(e.x, e.y - 28, this.player.x, this.player.y - 14);
        const sp = 400;
        this.addProjectile({
          x: e.x, y: e.y - 28, vx: Math.cos(a) * sp, vy: Math.sin(a) * sp,
          dmg: e.dmg * (e.weaken > 0 ? 0.6 : 1), radius: 6, enemy: true, type: 'arrow',
          color: '#ffb35a', life: 3,
        });
        this.audio.sfx('slash');
      }
      return;
    }
    if (e.state === 'recover') {
      e.stateT -= dt;
      if (e.stateT <= 0) e.state = 'chase';
      return;
    }
    e.windup = 0;
    if (e.cooldown <= 0 && d < 540) {
      e.state = 'windup'; e.stateT = 0.55; e.windup = 0.55;
      return;
    }
    let dx = 0, dy = 0;
    if (d < 230) { dx = (e.x - this.player.x) / d; dy = (e.y - this.player.y) / d; }
    else if (d > 360) { dx = (this.player.x - e.x) / d; dy = (this.player.y - e.y) / d; }
    else {
      const a = angleTo(e.x, e.y, this.player.x, this.player.y) + Math.PI / 2 * (e.seed % 2 > 1 ? 1 : -1);
      dx = Math.cos(a) * 0.6; dy = Math.sin(a) * 0.6;
    }
    this.enemyMove(e, dx, dy, 1, dt);
  },

  aiBrute(e, dt, d) {
    e.cooldown -= dt;
    if (e.state === 'windup') {
      e.stateT -= dt;
      e.windup = e.stateT;
      e.vx = damp(e.vx, 0, 8, dt); e.vy = damp(e.vy, 0, 8, dt);
      e.x += e.knockVx * dt; e.y += e.knockVy * dt;
      e.knockVx *= Math.exp(-7 * dt); e.knockVy *= Math.exp(-7 * dt);
      if (e.stateT <= 0) {
        e.state = 'recover'; e.stateT = 0.95; e.windup = 0; e.cooldown = 2.3 + rnd(0.7);
        e.state = 'recover';
        this.shake(7);
        this.audio.sfx('heavy');
        this.ring(e.x, e.y, 110, '#ff8a5a');
        this.burst(e.x, e.y, '#ff9a5a', 26, 240, 'spark');
        for (let i = 0; i < 6; i++) {
          this.particles.push({ x: e.x + rnd(80, -80), y: e.y + rnd(30, -30), vx: rnd(10, -10), vy: rnd(-40, -80), t: 0, life: rnd(0.8, 0.4), kind: 'ember', color: '#ff7a3a', size: rnd(3, 1) });
        }
        if (dist(e.x, e.y, this.player.x, this.player.y) < 112 + this.player.radius) {
          this.damagePlayer(e.dmg * (e.weaken > 0 ? 0.6 : 1), angleTo(e.x, e.y, this.player.x, this.player.y));
        }
      }
      return;
    }
    if (e.state === 'recover') {
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 6, dt); e.vy = damp(e.vy, 0, 6, dt);
      if (e.stateT <= 0) e.state = 'chase';
      return;
    }
    if (d < 120 && e.cooldown <= 0) { e.state = 'windup'; e.stateT = 0.85; e.windup = 0.85; return; }
    if (d > e.radius + 45) this.enemyMove(e, (this.player.x - e.x) / d, (this.player.y - e.y) / d, 1, dt);
    else this.enemyMove(e, 0, 0, 0, dt);
  },

  aiWitch(e, dt, d) {
    e.cooldown -= dt;
    if (e.state === 'windup') {
      e.stateT -= dt;
      e.vx = damp(e.vx, 0, 8, dt); e.vy = damp(e.vy, 0, 8, dt);
      e.x += e.knockVx * dt; e.y += e.knockVy * dt;
      e.knockVx *= Math.exp(-7 * dt); e.knockVy *= Math.exp(-7 * dt);
      if (e.stateT <= 0) {
        e.state = 'recover'; e.stateT = 0.5; e.cooldown = 2.4 + rnd(0.8);
        const base = angleTo(e.x, e.y - 30, this.player.x, this.player.y - 14);
        for (const off of [-0.26, 0, 0.26]) {
          this.addProjectile({
            x: e.x + Math.cos(base) * 16, y: e.y - 30 + Math.sin(base) * 16,
            vx: Math.cos(base + off) * 245, vy: Math.sin(base + off) * 245,
            dmg: e.dmg * (e.weaken > 0 ? 0.6 : 1) * 0.72, radius: 7, enemy: true, type: 'orb',
            color: '#c98aff', life: 4,
          });
        }
        this.audio.sfx('gate');
      }
      return;
    }
    if (e.state === 'recover') {
      e.stateT -= dt;
      if (e.stateT <= 0) e.state = 'chase';
      return;
    }
    if (d < 145 && e.cooldown < 0.4) {
      // blink away
      const pos = this.findSpawnPoint(260, 430);
      this.burst(e.x, e.y - 24, '#c98aff', 16, 150, 'spark');
      e.x = pos.x; e.y = pos.y;
      this.burst(e.x, e.y - 24, '#e0b0ff', 16, 150, 'spark');
      this.audio.sfx('dash');
      e.cooldown = Math.max(e.cooldown, 0.8);
      return;
    }
    if (e.cooldown <= 0 && d < 580) {
      e.state = 'windup'; e.stateT = 0.55;
      return;
    }
    let dx = 0, dy = 0;
    if (d < 250) { dx = (e.x - this.player.x) / d; dy = (e.y - this.player.y) / d; }
    else if (d > 400) { dx = (this.player.x - e.x) / d; dy = (this.player.y - e.y) / d; }
    else { const a = angleTo(e.x, e.y, this.player.x, this.player.y) + Math.PI / 2; dx = Math.cos(a) * 0.4; dy = Math.sin(a) * 0.4; }
    this.enemyMove(e, dx, dy, 1, dt);
  },

  // ================== BOSS ==================
  spawnBoss() {
    const run = this.run;
    const hp = Math.round(900 * (1 + (run.heat || 0) * 0.25));
    this.boss = {
      id: 'boss', isBoss: true, type: 'cerberus', name: 'ЦЕРБЕР',
      x: ROOM_W / 2, y: ROOM_H / 2 - 250,
      vx: 0, vy: 0, radius: 66, mass: 12,
      hp, maxHp: hp, dmg: 24 * (1 + (run.heat || 0) * 0.1),
      face: Math.PI / 2, state: 'chase', stateT: 0, cooldown: 1.6,
      attackDir: Math.PI / 2, pendingAttack: null, breathTick: 0,
      enraged: false, hurtFlash: 0, dead: false, spawnT: 1.1, hitThisAttack: false,
      walkPhase: 0, showHp: 0,
    };
    this.ring(this.boss.x, this.boss.y, 190, '#ff6a4a');
    this.shake(10);
    this.audio.sfx('boss');
    this.emit('hud');
  },

  updateBoss(dt) {
    const b = this.boss;
    if (!b || b.dead) return;
    const p = this.player;
    if (b.spawnT > 0) {
      b.spawnT -= dt;
      return;
    }
    if (b.hurtFlash > 0) b.hurtFlash -= dt;
    if (b.showHp > 0) b.showHp -= dt;
    if (!b.enraged && b.hp < b.maxHp * 0.5) {
      b.enraged = true;
      this.audio.sfx('boss');
      this.shake(14);
      this.ring(b.x, b.y, 220, '#ff4a2a');
      this.burst(b.x, b.y - 40, '#ff5a2a', 50, 300, 'ember');
      this.emit('banner', { eyebrow: 'ВТОРАЯ ЯРОСТЬ', title: 'ЗВЕРЬ РАЗЪЯРЁН', sub: 'ЦЕРБЕР НЕ ЗНАЕТ СТРАХА', cls: 'blood' });
    }
    const d = dist(b.x, b.y, p.x, p.y) || 1;
    const speedMul = b.enraged ? 1.35 : 1;
    // keep player outside the body
    if (d < b.radius * 0.7 + p.radius) {
      const nx = (p.x - b.x) / d, ny = (p.y - b.y) / d;
      p.x = b.x + nx * (b.radius * 0.7 + p.radius);
      p.y = b.y + ny * (b.radius * 0.7 + p.radius);
    }
    if (b.state === 'chase') {
      b.cooldown -= dt;
      b.face = approachAngle(b.face, angleTo(b.x, b.y, p.x, p.y), dt * 2.4);
      let dx = 0, dy = 0;
      if (d > 230) { dx = (p.x - b.x) / d; dy = (p.y - b.y) / d; }
      else { const a = angleTo(b.x, b.y, p.x, p.y) + Math.PI / 2; dx = Math.cos(a) * 0.3; dy = Math.sin(a) * 0.3; }
      const sp = (b.enraged ? 95 : 68);
      b.vx = damp(b.vx, dx * sp, 4, dt);
      b.vy = damp(b.vy, dy * sp, 4, dt);
      b.x += b.vx * dt; b.y += b.vy * dt;
      b.x = clamp(b.x, MARGIN + b.radius, ROOM_W - MARGIN - b.radius);
      b.y = clamp(b.y, MARGIN + b.radius, ROOM_H - MARGIN - b.radius);
      if (b.cooldown <= 0) this.startBossAttack();
      return;
    }
    if (b.state === 'windup') {
      b.stateT -= dt;
      b.vx = damp(b.vx, 0, 6, dt); b.vy = damp(b.vy, 0, 6, dt);
      if (b.pendingAttack !== 'charge') b.face = approachAngle(b.face, angleTo(b.x, b.y, p.x, p.y), dt * 1.2);
      if (b.stateT <= 0) this.releaseBossAttack();
      return;
    }
    if (b.state === 'charge') {
      b.stateT -= dt;
      const sp = (b.enraged ? 1500 : 1250);
      const nx = b.x + Math.cos(b.attackDir) * sp * dt;
      const ny = b.y + Math.sin(b.attackDir) * sp * dt;
      const hitWall = nx < MARGIN + b.radius || nx > ROOM_W - MARGIN - b.radius || ny < MARGIN + b.radius || ny > ROOM_H - MARGIN - b.radius;
      b.x = clamp(nx, MARGIN + b.radius, ROOM_W - MARGIN - b.radius);
      b.y = clamp(ny, MARGIN + b.radius, ROOM_H - MARGIN - b.radius);
      if (Math.random() < dt * 40) {
        this.particles.push({ x: b.x + rnd(40, -40), y: b.y + rnd(20, -10), vx: rnd(20, -20), vy: rnd(-10, -60), t: 0, life: 0.5, kind: 'ember', color: '#ff8a4a', size: rnd(4, 1.5) });
      }
      if (!b.hitThisAttack && dist(b.x, b.y, p.x, p.y) < b.radius * 0.8 + p.radius) {
        b.hitThisAttack = true;
        this.damagePlayer(b.dmg, b.attackDir);
      }
      if (b.stateT <= 0 || hitWall) {
        b.state = 'stagger'; b.stateT = hitWall ? 1.2 : 0.8; b.cooldown = 2.6;
        if (hitWall) {
          this.shake(16); this.audio.sfx('heavy');
          this.burst(b.x, b.y - 20, '#c9b090', 26, 260, 'piece');
          this.ring(b.x, b.y, 120, '#ffcf8a');
        }
      }
      return;
    }
    if (b.state === 'breath') {
      b.stateT -= dt;
      b.face = approachAngle(b.face, angleTo(b.x, b.y, p.x, p.y), dt * 0.55);
      b.breathTick -= dt;
      if (b.breathTick <= 0) {
        b.breathTick = 0.16;
        const a = angleTo(b.x, b.y, p.x, p.y);
        const diff = Math.abs(angleDiff(a, b.face));
        if (diff < 0.62 && d < 340) this.damagePlayer(7.5 * (1 + (this.run.heat || 0) * 0.1), b.face);
        // flames
        for (let i = 0; i < 4; i++) {
          const aa = b.face + rnd(0.5, -0.5);
          const rr = rnd(280, 40);
          this.particles.push({
            x: b.x + Math.cos(aa) * rr, y: b.y - 30 + Math.sin(aa) * rr * 0.6,
            vx: Math.cos(aa) * 220, vy: Math.sin(aa) * 190 - 60,
            t: 0, life: rnd(0.7, 0.35), kind: 'ember', color: pick(['#ffd27a', '#ff8a3a', '#ff5a2a']), size: rnd(5, 2),
          });
        }
        if (Math.random() < 0.3) {
          const tx = b.x + Math.cos(b.face + rnd(0.3, -0.3)) * rnd(240, 80);
          const ty = b.y + Math.sin(b.face + rnd(0.3, -0.3)) * rnd(160, 50);
          this.zones.push({ x: tx, y: ty, r: 46, life: 4.5, tick: 0.2, dmg: 6, color: '#ff7a3a' });
        }
      }
      if (b.stateT <= 0) { b.state = 'recover'; b.stateT = 0.75; b.cooldown = 3.4; }
      return;
    }
    if (b.state === 'slam') {
      b.stateT -= dt;
      b.vx = 0; b.vy = 0;
      if (b.stateT <= 0) {
        const radius = 195;
        this.ring(b.x, b.y, radius, '#ff8a4a');
        this.burst(b.x, b.y, '#ff9a5a', 34, 300, 'spark');
        this.shake(18);
        this.audio.sfx('heavy');
        for (let i = 0; i < 10; i++) {
          const a = (i / 10) * TAU;
          this.zones.push({ x: b.x + Math.cos(a) * rnd(140, 40), y: b.y + Math.sin(a) * rnd(90, 20), r: 38, life: 3.2, tick: 0.3, dmg: 5, color: '#ff7a3a' });
        }
        if (dist(b.x, b.y, p.x, p.y) < radius + p.radius) this.damagePlayer(b.dmg * 1.1, angleTo(b.x, b.y, p.x, p.y));
        b.state = 'recover'; b.stateT = 1.0; b.cooldown = 3.1;
      }
      return;
    }
    if (b.state === 'summon') {
      b.stateT -= dt;
      if (b.stateT <= 0) {
        let spawned = 0;
        for (let i = 0; i < 2; i++) {
          const pos = this.findSpawnPoint(240, 420);
          const e = this.addEnemy(i === 0 ? 'shade' : 'skeleton', pos.x, pos.y, {});
          e.spawnT = 0.7;
          e.hp *= 0.9; e.maxHp *= 0.9;
          this.ring(pos.x, pos.y, 50, '#ff8a5a');
          spawned++;
        }
        this.audio.sfx('boss');
        b.state = 'recover'; b.stateT = 1.0; b.cooldown = 5.5;
      }
      return;
    }
    if (b.state === 'recover' || b.state === 'stagger') {
      b.stateT -= dt;
      b.vx = damp(b.vx, 0, 5, dt); b.vy = damp(b.vy, 0, 5, dt);
      if (b.stateT <= 0) b.state = 'chase';
      return;
    }
  },

  startBossAttack() {
    const b = this.boss, p = this.player;
    const d = dist(b.x, b.y, p.x, p.y);
    const r = Math.random();
    let attack;
    if (b.enraged) {
      if (d > 360) attack = r < 0.55 ? 'charge' : r < 0.85 ? 'breath' : 'summon';
      else attack = r < 0.34 ? 'slam' : r < 0.68 ? 'breath' : r < 0.9 ? 'charge' : 'summon';
    } else {
      if (d > 360) attack = r < 0.5 ? 'charge' : r < 0.82 ? 'breath' : 'summon';
      else attack = r < 0.32 ? 'slam' : r < 0.62 ? 'breath' : r < 0.86 ? 'charge' : 'summon';
    }
    if (attack === 'summon' && this.enemies.length >= 3) attack = 'slam';
    b.pendingAttack = attack;
    b.attackDir = angleTo(b.x, b.y, p.x, p.y);
    b.hitThisAttack = false;
    b.state = 'windup';
    b.stateT = attack === 'charge' ? 0.8 : attack === 'breath' ? 0.72 : attack === 'summon' ? 1.0 : 0.95;
    if (attack !== 'charge') b.face = b.attackDir;
    this.audio.sfx('boss');
    if (attack === 'summon') this.audio.sfx('rage');
  },

  releaseBossAttack() {
    const b = this.boss;
    if (b.pendingAttack === 'charge') {
      b.state = 'charge'; b.stateT = 0.52; b.hitThisAttack = false;
      this.audio.sfx('dash');
      this.shake(6);
    } else if (b.pendingAttack === 'breath') {
      b.state = 'breath'; b.stateT = 1.5; b.breathTick = 0;
      this.audio.sfx('rage');
    } else if (b.pendingAttack === 'summon') {
      b.state = 'summon'; b.stateT = 0.55;
    } else {
      b.state = 'slam'; b.stateT = 0.45;
    }
    b.pendingAttack = null;
  },

  // ================== DEATH ==================
  killEnemy(e, silent = false) {
    if (!e || e.dead) return;
    if (e === this.boss) {
      e.dead = true; e.hp = 0;
      this.run.kills++;
      this.run.darkEarned += 50;
      this.run.obols += 40;
      this.shake(22);
      this.burst(e.x, e.y - 40, '#ff8a4a', 70, 380, 'ember');
      this.burst(e.x, e.y - 40, '#ffd27a', 40, 320, 'spark');
      this.ring(e.x, e.y, 260, '#ffb06a');
      this.particles.push({ x: e.x, y: e.y, vx: 0, vy: 0, t: 0, life: 1.2, kind: 'ring', color: '#ffd28a', size: 30, grow: 380, w: 5 });
      this.audio.sfx('victory');
      this.finishVictory();
      return;
    }
    e.dead = true;
    const run = this.run;
    run.kills++;
    run.obols += e.elite ? 12 : 2;
    run.darkEarned += e.elite ? 8 : 1;
    run.rage = clamp(run.rage + 4, 0, run.rageMax);
    const colors = { skeleton: '#d8cbb2', shade: '#77e4ff', archer: '#ffb35a', brute: '#ff7a5a', witch: '#d0a0ff' };
    const color = colors[e.type] || '#ffcf8a';
    this.burst(e.x, e.y - e.radius, color, e.elite ? 26 : 14, e.elite ? 260 : 170, 'spark');
    this.burst(e.x, e.y - e.radius, '#8f2b32', 10, 150, 'blood');
    this.particles.push({ x: e.x, y: e.y - e.radius * 1.6, vx: rnd(15, -15), vy: -55, t: 0, life: 1.1, kind: 'soul', color, size: 4 });
    this.spawnDecal(e.x, e.y, '#5d1820', e.radius * 1.6);
    if (e.elite) {
      this.ring(e.x, e.y, 70, '#ffcf6a');
      for (let i = 0; i < 6; i++) this.particles.push({ x: e.x + rnd(20, -20), y: e.y + rnd(14, -14), vx: rnd(40, -40), vy: rnd(-30, -90), t: 0, life: 0.8, kind: 'ember', color: '#ffcf6a', size: 2.4 });
      this.shake(6);
    }
    if (!silent) this.audio.sfx(e.elite ? 'heavy' : 'hit');
    if (run.stats.ruinDmg) {
      this.ring(e.x, e.y, 100, '#ff6a4a');
      const others = this.enemies.filter((o) => o !== e && !o.dead && dist(o.x, o.y, e.x, e.y) < 120);
      for (const o of others) this.damageEnemy(o, run.stats.ruinDmg, { direct: false, raw: true });
      if (this.boss && !this.boss.dead && dist(this.boss.x, this.boss.y, e.x, e.y) < 140) {
        this.damageEnemy(this.boss, run.stats.ruinDmg, { direct: false, raw: true });
      }
    }
    if (run.stats.healOnKill && chance(run.stats.healOnKillChance)) {
      this.heal(run.stats.healOnKill);
      this.particles.push({ x: e.x, y: e.y - 10, vx: 0, vy: -40, t: 0, life: 0.7, kind: 'ember', color: '#9cf0a8', size: 3 });
    }
  },
};

// World rendering.
import { TAU, clamp, lerp, damp, rnd, angleTo, angleDiff } from './core.js';
import {
  drawGlow, drawPlayer, drawEnemy, drawBoss, drawSlash, drawParticle,
  drawProjectileArt, drawPillar, drawRubble, drawBrazier, rgba,
} from './art.js';
import { ROOM_W, ROOM_H, MARGIN } from './constants.js';
import { drawMenu } from './art.js';

export const renderMethods = {
  render(t) {
    const ctx = this.ctx;
    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);
    ctx.clearRect(0, 0, this.w, this.h);
    if (!this.run || !this.floor) return;
    const biome = this.biome;
    ctx.fillStyle = biome.bg;
    ctx.fillRect(0, 0, this.w, this.h);

    const sh = this.shakeAmount;
    const shx = sh ? rnd(sh, -sh) : 0;
    const shy = sh ? rnd(sh, -sh) : 0;
    const p = this.player;

    ctx.save();
    ctx.translate(this.w / 2, this.h / 2);
    ctx.scale(this.scale, this.scale);
    ctx.translate(-this.cam.x + shx, -this.cam.y + shy);

    ctx.drawImage(this.floor, 0, 0);

    // blood / scorch decals
    if (this.decals && this.decals.length) {
      for (const d of this.decals) {
        ctx.save();
        ctx.translate(d.x, d.y);
        ctx.rotate(d.rot);
        const grd = ctx.createRadialGradient(0, 0, 0, 0, 0, d.size);
        grd.addColorStop(0, rgba(d.color, 0.5));
        grd.addColorStop(1, rgba(d.color, 0));
        ctx.fillStyle = grd;
        ctx.beginPath(); ctx.ellipse(0, 0, d.size, d.size * 0.55, 0, 0, TAU); ctx.fill();
        ctx.restore();
      }
    }

    this.drawAmbientDust(ctx, t);
    this.drawBrazierLight(ctx);
    this.drawZones(ctx, t);
    this.drawSpawnMarkers(ctx, t);
    this.drawTelegraphs(ctx, t);

    // movement ring under player
    if (p) {
      ctx.strokeStyle = 'rgba(227,189,123,.18)';
      ctx.lineWidth = 1.5;
      ctx.beginPath();
      ctx.ellipse(p.x, p.y + 2, 22, 8, 0, 0, TAU);
      ctx.stroke();
    }
    if (this.boss && !this.boss.dead) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      drawGlow(ctx, this.boss.enraged ? '#ff3a1a' : '#ff7a3a', this.boss.x, this.boss.y - 30, 160, 0.16);
      ctx.restore();
      ctx.strokeStyle = this.boss.enraged ? 'rgba(255,80,50,.35)' : 'rgba(255,140,80,.22)';
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(this.boss.x, this.boss.y + 6, 100, 30, 0, 0, TAU); ctx.stroke();
    }

    // y-sorted props and actors
    const drawables = [];
    for (const o of this.obstacles) drawables.push({ y: o.y, kind: 'obstacle', o });
    for (const b of this.braziers) drawables.push({ y: b.y, kind: 'brazier', o: b });
    for (const e of this.enemies) if (!e.dead) drawables.push({ y: e.y, kind: 'enemy', e });
    if (this.boss && !this.boss.dead) drawables.push({ y: this.boss.y + 20, kind: 'boss', b: this.boss });
    if (p && this.state !== 'dead') drawables.push({ y: p.y + 2, kind: 'player' });
    drawables.sort((a, b) => a.y - b.y);

    for (const d of drawables) {
      if (d.kind === 'obstacle') {
        if (d.o.type === 'pillar') drawPillar(ctx, d.o, biome, t);
        else drawRubble(ctx, d.o, biome);
      } else if (d.kind === 'brazier') drawBrazier(ctx, d.o, biome.ember, t);
      else if (d.kind === 'enemy') {
        const e = d.e;
        const alpha = e.spawnT > 0 ? clamp(1 - e.spawnT / 0.55, 0, 1) : 1;
        if (alpha < 1) {
          ctx.save();
          ctx.globalAlpha = alpha;
          ctx.translate(0, (1 - alpha) * 20);
          drawEnemy(ctx, e, t);
          ctx.restore();
          ctx.save();
          ctx.globalCompositeOperation = 'lighter';
          drawGlow(ctx, e.elite ? '#ffcf6a' : '#b98cf0', e.x, e.y - 10, 55 * alpha, 0.4);
          ctx.restore();
        } else drawEnemy(ctx, e, t);
      } else if (d.kind === 'boss') {
        const b = d.b;
        if (b.spawnT > 0) {
          const a = clamp(1 - b.spawnT, 0.15, 1);
          ctx.save(); ctx.globalAlpha = a; drawBoss(ctx, b, t); ctx.restore();
        } else drawBoss(ctx, b, t);
      } else if (d.kind === 'player') {
        drawPlayer(ctx, p, t, this.run.weapon);
      }
    }

    // projectiles
    for (const pr of this.projectiles) {
      ctx.save();
      if (pr.type === 'arrow' || pr.type === 'orb' || pr.type === 'spear') {
        ctx.globalCompositeOperation = 'lighter';
        drawGlow(ctx, pr.enemy ? (pr.color || '#ff9a5a') : '#d8ffa0', pr.x, pr.y, 18, 0.25);
        ctx.globalCompositeOperation = 'source-over';
      }
      drawProjectileArt(ctx, pr, t);
      ctx.restore();
    }

    // particles (world)
    for (const pa of this.particles) drawParticle(ctx, pa);
    // slashes
    for (const s of this.slashes) drawSlash(ctx, s);
    // bolts
    this.drawBolts(ctx, t);

    // aim reticle
    if (p && this.state === 'fight' && !this.input.usingTouch && performance.now() - this.input.mouse.lastMove < 2800) {
      const wx = this.cam.x + (this.input.mouse.x - this.w / 2) / this.scale;
      const wy = this.cam.y + (this.input.mouse.y - this.h / 2) / this.scale;
      ctx.save();
      ctx.strokeStyle = 'rgba(247,230,189,.55)';
      ctx.lineWidth = 1.3;
      ctx.beginPath(); ctx.arc(wx, wy, 7, 0, TAU); ctx.stroke();
      for (let i = 0; i < 4; i++) {
        const a = i * Math.PI / 2;
        ctx.beginPath();
        ctx.moveTo(wx + Math.cos(a) * 10, wy + Math.sin(a) * 10);
        ctx.lineTo(wx + Math.cos(a) * 15, wy + Math.sin(a) * 15);
        ctx.stroke();
      }
      ctx.fillStyle = 'rgba(247,230,189,.8)';
      ctx.beginPath(); ctx.arc(wx, wy, 1.4, 0, TAU); ctx.fill();
      ctx.restore();
    }

    // player warm light
    if (p) {
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      drawGlow(ctx, '#ffd7a0', p.x, p.y - 30, 180, 0.1);
      ctx.restore();
    }
    ctx.restore();

    // ---------- screen space ----------
    this.drawScreenAtmosphere(ctx, t);
  },

  drawAmbientDust(ctx, t) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const d of this.dust) {
      const a = 0.08 + 0.1 * (0.5 + Math.sin(d.phase) * 0.5);
      ctx.fillStyle = rgba(this.biome.ember, a);
      ctx.beginPath();
      ctx.arc(d.x, d.y + Math.sin(d.phase + t) * 6, d.size, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  },

  drawBrazierLight(ctx) {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    for (const b of this.braziers) {
      drawGlow(ctx, this.biome.ember, b.x, b.y - 30, 130, 0.22);
    }
    ctx.restore();
  },

  drawZones(ctx, t) {
    for (const z of this.zones) {
      const a = clamp(z.life / 1.2, 0, 1);
      ctx.save();
      const grd = ctx.createRadialGradient(z.x, z.y, 0, z.x, z.y, z.r);
      grd.addColorStop(0, rgba('#ff5a2a', 0.28 * a));
      grd.addColorStop(0.6, rgba('#ff3a1a', 0.18 * a));
      grd.addColorStop(1, rgba('#ff3a1a', 0));
      ctx.fillStyle = grd;
      ctx.beginPath(); ctx.ellipse(z.x, z.y, z.r, z.r * 0.55, 0, 0, TAU); ctx.fill();
      ctx.strokeStyle = rgba('#ff8a4a', (0.35 + Math.sin(t * 8 + z.x) * 0.12) * a);
      ctx.lineWidth = 1.6;
      ctx.beginPath(); ctx.ellipse(z.x, z.y, z.r * 0.8, z.r * 0.44, 0, 0, TAU); ctx.stroke();
      ctx.restore();
    }
  },

  drawSpawnMarkers(ctx, t) {
    for (const s of this.spawnQueue) {
      if (s.spawned) continue;
      const prog = 1 - clamp(s.delay / 0.62, 0, 1);
      const color = s.elite ? '#ffcf6a' : '#c08cff';
      const a = 0.4 + Math.sin(t * 8) * 0.2;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      drawGlow(ctx, color, s.x, s.y - 10, 46, a);
      ctx.strokeStyle = rgba(color, 0.65);
      ctx.lineWidth = 2;
      ctx.beginPath(); ctx.ellipse(s.x, s.y, 34, 14, 0, 0, TAU); ctx.stroke();
      ctx.strokeStyle = rgba(color, 0.9);
      ctx.beginPath(); ctx.arc(s.x, s.y - 6, 26, -Math.PI / 2, -Math.PI / 2 + prog * TAU); ctx.stroke();
      ctx.strokeStyle = rgba(color, 0.4);
      ctx.beginPath();
      ctx.moveTo(s.x, s.y + 20); ctx.lineTo(s.x, s.y - 70);
      ctx.stroke();
      ctx.restore();
    }
  },

  drawTelegraphs(ctx, t) {
    const p = this.player;
    for (const e of this.enemies) {
      if (e.dead || e.spawnT > 0) continue;
      const progress = e.state === 'windup' ? 1 - clamp(e.stateT / (e.kind === 'slam' ? 0.85 : 0.55), 0, 1) : 1;
      const pulse = 0.45 + Math.sin(t * 12) * 0.18;
      ctx.save();
      if (e.state === 'windup') {
        if (e.kind === 'melee' || e.kind === 'dash') {
          const range = e.kind === 'dash' ? 260 : e.radius + 60;
          ctx.translate(e.x, e.y);
          ctx.rotate(e.face);
          ctx.fillStyle = `rgba(220,50,40,${0.1 + progress * 0.16})`;
          ctx.beginPath();
          ctx.moveTo(0, -e.radius * 0.6);
          ctx.lineTo(range, -range * 0.25);
          ctx.lineTo(range, range * 0.25);
          ctx.lineTo(0, e.radius * 0.6);
          ctx.closePath(); ctx.fill();
          ctx.strokeStyle = `rgba(255,90,70,${pulse})`; ctx.lineWidth = 1.4;
          ctx.beginPath(); ctx.moveTo(0, -e.radius * 0.6); ctx.lineTo(range, -range * 0.25); ctx.stroke();
          ctx.beginPath(); ctx.moveTo(0, e.radius * 0.6); ctx.lineTo(range, range * 0.25); ctx.stroke();
        } else if (e.kind === 'ranged') {
          ctx.strokeStyle = `rgba(255,140,60,${pulse * 0.7})`;
          ctx.setLineDash([8, 7]); ctx.lineWidth = 1.2;
          ctx.beginPath(); ctx.moveTo(e.x, e.y - 28); ctx.lineTo(p.x, p.y - 12); ctx.stroke();
          ctx.setLineDash([]);
        } else if (e.kind === 'slam') {
          ctx.fillStyle = `rgba(220,50,40,${0.08 + progress * 0.14})`;
          ctx.strokeStyle = `rgba(255,100,60,${pulse})`;
          ctx.lineWidth = 2;
          ctx.beginPath(); ctx.ellipse(e.x, e.y, 112, 50, 0, 0, TAU); ctx.fill(); ctx.stroke();
          ctx.beginPath(); ctx.ellipse(e.x, e.y, 112 * progress, 50 * progress, 0, 0, TAU); ctx.stroke();
        } else if (e.kind === 'caster') {
          ctx.strokeStyle = `rgba(200,140,255,${pulse})`;
          ctx.lineWidth = 1.5;
          ctx.beginPath(); ctx.arc(e.x, e.y - 30, 22 + progress * 8, 0, TAU); ctx.stroke();
        }
      }
      ctx.restore();
    }
    const b = this.boss;
    if (b && !b.dead && b.spawnT <= 0) {
      const pulse = 0.5 + Math.sin(t * 10) * 0.2;
      ctx.save();
      if (b.state === 'windup' && b.pendingAttack === 'charge') {
        ctx.translate(b.x, b.y);
        ctx.rotate(b.attackDir);
        const len = 1100;
        ctx.fillStyle = `rgba(230,60,35,${0.14 + pulse * 0.12})`;
        ctx.beginPath();
        ctx.moveTo(0, -b.radius * 0.7);
        ctx.lineTo(len, -b.radius * 0.9);
        ctx.lineTo(len, b.radius * 0.9);
        ctx.lineTo(0, b.radius * 0.7);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = `rgba(255,120,80,${pulse})`; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.moveTo(b.radius, 0); ctx.lineTo(len, 0); ctx.stroke();
      } else if (b.state === 'windup' && b.pendingAttack === 'breath') {
        ctx.translate(b.x, b.y - 20);
        ctx.rotate(angleTo(b.x, b.y, p.x, p.y));
        const len = 340, spread = 0.62;
        ctx.fillStyle = `rgba(230,80,40,${0.1 + pulse * 0.1})`;
        ctx.beginPath(); ctx.moveTo(0, 0);
        ctx.arc(0, 0, len, -spread, spread);
        ctx.closePath(); ctx.fill();
        ctx.strokeStyle = `rgba(255,140,80,${pulse})`; ctx.lineWidth = 1.5;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(-spread) * len, Math.sin(-spread) * len); ctx.moveTo(0, 0); ctx.lineTo(Math.cos(spread) * len, Math.sin(spread) * len); ctx.stroke();
      } else if (b.state === 'windup' && b.pendingAttack === 'slam') {
        ctx.strokeStyle = `rgba(255,100,60,${pulse})`;
        ctx.fillStyle = `rgba(220,50,40,${0.12})`;
        ctx.lineWidth = 2.5;
        ctx.beginPath(); ctx.ellipse(b.x, b.y, 195, 90, 0, 0, TAU); ctx.fill(); ctx.stroke();
        ctx.beginPath(); ctx.ellipse(b.x, b.y, 195 * (1 - b.stateT / 0.95), 90 * (1 - b.stateT / 0.95), 0, 0, TAU); ctx.stroke();
      } else if (b.state === 'windup' && b.pendingAttack === 'summon') {
        ctx.strokeStyle = `rgba(255,120,80,${pulse})`; ctx.lineWidth = 2;
        ctx.beginPath(); ctx.arc(b.x, b.y - 20, 90 + Math.sin(t * 6) * 8, 0, TAU); ctx.stroke();
      } else if (b.state === 'breath') {
        ctx.translate(b.x, b.y - 20);
        ctx.rotate(b.face);
        const len = 340, spread = 0.62;
        const grd = ctx.createRadialGradient(0, 0, 20, 0, 0, len);
        grd.addColorStop(0, 'rgba(255,150,60,.28)');
        grd.addColorStop(0.7, 'rgba(255,90,30,.12)');
        grd.addColorStop(1, 'rgba(255,60,20,0)');
        ctx.fillStyle = grd;
        ctx.beginPath(); ctx.moveTo(0, 0); ctx.arc(0, 0, len, -spread, spread); ctx.closePath(); ctx.fill();
      } else if (b.state === 'slam') {
        const prog = 1 - b.stateT / 0.45;
        ctx.strokeStyle = `rgba(255,110,60,${pulse})`; ctx.lineWidth = 3;
        ctx.beginPath(); ctx.ellipse(b.x, b.y, 195 * prog, 90 * prog, 0, 0, TAU); ctx.stroke();
      }
      ctx.restore();
    }
  },

  drawBolts(ctx, t) {
    for (const b of this.bolts) {
      const a = 1 - b.t / b.life;
      ctx.save();
      ctx.globalCompositeOperation = 'lighter';
      ctx.strokeStyle = rgba(b.color, 0.25 * a);
      ctx.lineWidth = 8;
      ctx.beginPath();
      b.pts.forEach((pt, i) => (i ? ctx.lineTo(pt.x, pt.y) : ctx.moveTo(pt.x, pt.y)));
      ctx.stroke();
      ctx.strokeStyle = rgba('#ffffff', 0.9 * a);
      ctx.lineWidth = 2;
      ctx.stroke();
      ctx.restore();
    }
  },

  drawScreenAtmosphere(ctx, t) {
    const w = this.w, h = this.h;
    const p = this.player;
    // low hp vignette
    const hpFrac = this.run ? this.run.hp / this.run.maxHp : 1;
    if (hpFrac < 0.36 && this.state !== 'dead') {
      const pulse = 0.55 + Math.sin(t * 5) * 0.25;
      const grd = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.28, w / 2, h / 2, Math.max(w, h) * 0.72);
      grd.addColorStop(0, 'rgba(120,10,14,0)');
      grd.addColorStop(1, `rgba(130,14,18,${0.28 * pulse})`);
      ctx.fillStyle = grd;
      ctx.fillRect(0, 0, w, h);
    }
    if (this.run && this.run.rageActive > 0) {
      const grd = ctx.createRadialGradient(w / 2, h / 2, Math.min(w, h) * 0.3, w / 2, h / 2, Math.max(w, h) * 0.7);
      grd.addColorStop(0, 'rgba(255,110,60,0)');
      grd.addColorStop(1, `rgba(210,70,30,${0.14 + Math.sin(t * 9) * 0.04})`);
      ctx.fillStyle = grd;
      ctx.fillRect(0, 0, w, h);
    }
    // drifting fog
    const biome = this.biome;
    ctx.save();
    for (let i = 0; i < 3; i++) {
      const sx = ((t * (8 + i * 5) + i * 640) % (w + 700)) - 350;
      const sy = h * (0.25 + i * 0.22);
      const rr = w * (0.35 + i * 0.08);
      const grd = ctx.createRadialGradient(sx, sy, 0, sx, sy, rr);
      grd.addColorStop(0, rgba(biome.fog, 0.16));
      grd.addColorStop(1, rgba(biome.fog, 0));
      ctx.fillStyle = grd;
      ctx.beginPath(); ctx.arc(sx, sy, rr, 0, TAU); ctx.fill();
    }
    ctx.restore();
    // intro / death dim
    let dim = 0;
    if (this.state === 'intro') dim = clamp(this.introT * 0.22, 0, 0.4);
    if (this.state === 'dying' || this.state === 'dead') dim = 0.45;
    if (dim > 0) {
      ctx.fillStyle = `rgba(5,2,7,${dim})`;
      ctx.fillRect(0, 0, w, h);
    }
    // cinematic letterbox feel
    const top = ctx.createLinearGradient(0, 0, 0, h * 0.16);
    top.addColorStop(0, 'rgba(2,1,4,.45)'); top.addColorStop(1, 'rgba(2,1,4,0)');
    ctx.fillStyle = top; ctx.fillRect(0, 0, w, h * 0.16);
    const bot = ctx.createLinearGradient(0, h * 0.84, 0, h);
    bot.addColorStop(0, 'rgba(2,1,4,0)'); bot.addColorStop(1, 'rgba(2,1,4,.5)');
    ctx.fillStyle = bot; ctx.fillRect(0, h * 0.84, w, h * 0.16);
  },

  drawMenu(ctx, t) {
    drawMenu(ctx, this.w, this.h, t);
  },
};

