170:     let attackSpeed = hs.attackSpeed;
171:     if (has('artemis_haste')) attackSpeed *= 1 + v('artemis_haste', 16) / 100;
172: 
173:     run.stats = {
174:       maxHp: Math.round(maxHp),
175:       dmgMult,
176:       moveSpeed: PLAYER_BASE_SPEED * moveMult,
177:       critChance: clamp(0.05 + (meta.crit || 0) * 0.05 + (has('artemis_crit') ? v('artemis_crit', 15) / 100 : 0) + (has('athena_strategy') ? v('athena_strategy', 14) * 0.004 : 0), 0, 0.85),
178:       critMult: 2.1,
179:       attackSpeed,
180:       rangeMult: hs.rangeMult,
181:       pierce: hs.pierce,
182:       specialMult: hs.specialMult * (1 + (has('chaos_mark') ? v('chaos_mark', 30) / 100 : 0)),
183:       specialCd: (w.attack.special.cd) * hs.specialCd,
184:       specialRadius: hs.specialRadius,
185:       dashMax: 1 + (meta.dash || 0) + (has('hermes_shadow') ? 1 : 0),
186:       dashCd,
187:       dashDist: 1 + (has('hermes_wind') ? v('hermes_wind', 20) / 100 : 0),
188:       shieldCharges: has('athena_aegis') ? 1 : 0,
189:       damageTaken: clamp(1 + (has('chaos_gift') ? 0.15 : 0) - (has('chaos_armor') ? 0.12 : 0), 0.6, 1.6),
190:       lifesteal: has('ares_blood') ? v('ares_blood', 1.4) : 0,
191:       arrows: hs.arrows,
192:       spread: hs.spread,
193:       // boon payloads
194:       lightningDmg: has('zeus_bolt') ? v('zeus_bolt', 26) : 0,
195:       lightningChance: 0.34,
196:       zeusStepDmg: has('zeus_step') ? v('zeus_step', 24) : 0,
197:       poseidonWave: has('poseidon_wave') > 0,
198:       poseidonSpecial: has('poseidon_special') ? v('poseidon_special', 42) : 0,
199:       poseidonTide: has('poseidon_tide') ? v('poseidon_tide', 30) : 0,
200:       zeusStorm: has('zeus_storm') ? v('zeus_storm', 42) : 0,
201:       artemisMark: has('artemis_mark') ? v('artemis_mark', 46) : 0,
202:       poisonDps: has('dionysus_poison') ? v('dionysus_poison', 8) : 0,
203:       poisonSlow: has('dionysus_daze') ? v('dionysus_daze', 22) : 0,
204:       doomDmg: has('ares_doom') ? v('ares_doom', 52) : 0,
205:       ruinDmg: has('ares_ruin') ? v('ares_ruin', 34) : 0,
206:       weakAmount: has('aphrodite_charm') ? v('aphrodite_charm', 32) / 100 : 0,
207:       healOnKill: has('dionysus_feast') ? v('dionysus_feast', 5) : 0,
208:       healOnKillChance: 0.38,
209:       critDmgBonus: has('artemis_crit') ? 0.6 : 0,
210:     };
211:     run.stats.critMult += run.stats.critDmgBonus;
212:     run.maxHp = run.stats.maxHp;
213:     if (run.hp > run.maxHp) run.hp = run.maxHp;
214:     if (run.hp < run.maxHp && run.maxHp > oldMax) run.hp += run.maxHp - oldMax;
215:     if (run.hp <= 0) run.hp = 1;
216:   }
