218:   // ============ chambers ============
219:   startChamber(n) {
220:     const run = this.run;
221:     run.chamber = n;
222:     const biome = chamberBiome(n);
223:     this.biome = biome;
224:     this.floor = buildFloor(biome, 9001 + n * 733, ROOM_W, ROOM_H);
225:     this.buildRoom(n, biome);
226: 
227:     this.enemies = []; this.projectiles = []; this.particles = [];
228:     this.slashes = []; this.bolts = []; this.zones = []; this.spawnQueue = [];
229:     this.boss = null;
230:     this.decals = [];
231:     this.waveDelay = 0; this.clearDelay = 0;
232:     run.attackCd = 0; run.attackBuffer = 0; run.comboIdx = 0; run.comboTimer = 0;
233:     run.specialCd = 0; run.shield = run.stats.shieldCharges;
234:     run.dashCharges = run.stats.dashMax; run.dashRegen = 0;
235:     run.rageActive = 0;
236: 
237:     const p = this.player;
238:     p.x = ROOM_W / 2; p.y = ROOM_H / 2 + 110;
239:     p.vx = 0; p.vy = 0; p.invuln = 0.8; p.hurtFlash = 0; p.dashing = false;
240:     p.dashTime = 0; p.dashTrail = []; p.scarf = []; p.face = -Math.PI / 2;
241:     this.cam.x = p.x; this.cam.y = p.y;
242: 
243:     const bossRoom = n >= TOTAL_CHAMBERS;
244:     run.bossSeen = bossRoom;
245:     run.wave = 0;
246:     if (bossRoom) {
247:       run.wavesTotal = 1;
248:       run.waveCounts = [];
249:       this.emit('banner', { eyebrow: biome.chapter, title: 'ЦЕРБЕР', sub: 'СТРАЖ СТИКСА · ПОСЛЕДНИЙ РУБЕЖ', cls: 'blood' });
250:       this.audio.sfx('boss');
251:     } else {
252:       const total = Math.min(12, 3 + Math.floor(n * 0.95));
253:       const waves = n >= 7 ? 3 : 2;
254:       const counts = [];
255:       let left = total;
256:       for (let i = 0; i < waves; i++) {
257:         const c = i === waves - 1 ? left : Math.max(1, Math.round(total / waves * (0.82 + Math.random() * 0.3)));
258:         counts.push(c); left -= c;
259:       }
260:       if (left > 0) counts[counts.length - 1] += left;
261:       run.waveCounts = counts;
262:       run.wavesTotal = waves;
263:       this.emit('banner', { eyebrow: biome.chapter, title: biome.name, sub: `ЗАЛ ${roman(n)} · ${biome.sub}`, cls: '' });
264:     }
265:     this.state = 'intro';
266:     this.introT = bossRoom ? 2.4 : 1.55;
267:     this.emit('hud');
268:   }
