270:   buildRoom(n, biome) {
271:     const R = mulberry32(4400 + n * 71);
272:     const bossRoom = n >= TOTAL_CHAMBERS;
273:     this.obstacles = [];
274:     this.braziers = [];
275:     const count = bossRoom ? 3 : 5 + ((R() * 3) | 0);
276:     let guard = 0;
277:     while (this.obstacles.length < count && guard++ < 80) {
278:       const x = MARGIN + 180 + R() * (ROOM_W - MARGIN * 2 - 360);
279:       const y = MARGIN + 170 + R() * (ROOM_H - MARGIN * 2 - 340);
280:       if (dist(x, y, ROOM_W / 2, ROOM_H / 2) < 260) continue;
281:       if (bossRoom && dist(x, y, ROOM_W / 2, ROOM_H / 2 - 260) < 260) continue;
282:       if (this.obstacles.some((o) => dist(x, y, o.x, o.y) < 220)) continue;
283:       const type = R() < 0.58 ? 'pillar' : 'rubble';
284:       const r = type === 'pillar' ? 33 : 25;
285:       this.obstacles.push({ x, y, r, type, seed: (R() * 1e6) | 0 });
286:     }
287:     const bxs = [MARGIN + 100, ROOM_W - MARGIN - 100];
288:     const bys = [MARGIN + 100, ROOM_H - MARGIN - 100];
289:     for (const x of bxs) for (const y of bys) this.braziers.push({ x, y });
290:     // extra wall braziers
291:     if (!bossRoom) {
292:       this.braziers.push({ x: ROOM_W / 2, y: MARGIN + 100 });
293:       this.braziers.push({ x: ROOM_W / 2, y: ROOM_H - MARGIN - 100 });
294:     }
295:   }
296: 
297:   addEnemy(typeId, x, y, opts = {}) {
298:     const base = ENEMY_TYPES[typeId];
299:     const n = this.run.chamber;
300:     const heat = this.run.heat || 0;
301:     const elite = !!opts.elite;
302:     const hpMul = (1 + (n - 1) * 0.15 + heat * 0.17) * (elite ? 2.1 : 1);
303:     const dmgMul = (1 + (n - 1) * 0.085 + heat * 0.1) * (elite ? 1.35 : 1);
304:     const e = {
305:       id: Math.random().toString(36).slice(2),
306:       type: typeId, kind: base.kind,
307:       x, y, vx: 0, vy: 0, knockVx: 0, knockVy: 0,
308:       radius: base.radius * (elite ? 1.24 : 1),
309:       hp: base.hp * hpMul, maxHp: base.hp * hpMul,
310:       speed: base.speed * (elite ? 1.06 : 1),
311:       dmg: base.dmg * dmgMul,
312:       elite, mass: base.mass * (elite ? 1.5 : 1),
313:       state: 'chase', stateT: 0, cooldown: rnd(1.2, 0.4), windup: 0,
314:       face: angleTo(x, y, this.player.x, this.player.y),
315:       walkPhase: rnd(TAU), hurtFlash: 0, showHp: 0, dead: false,
316:       poison: 0, poisonStacks: 0, poisonTick: 0, doom: 0, doomDmg: 0,
317:       weaken: 0, slow: 0, slowAmt: 0, orbitPhase: rnd(TAU),
318:       spawnT: 0.55, hitThisAttack: false, attackDir: 0, enraged: false,
319:       seed: Math.random() * 1000,
320:     };
321:     this.enemies.push(e);
322:     return e;
323:   }
324: 
325:   spawnWave() {
326:     const run = this.run;
327:     const n = run.chamber;
328:     const count = run.waveCounts[run.wave] || 3;
329:     const pool = ['skeleton', 'skeleton'];
330:     if (n >= 2) pool.push('shade', 'archer');
331:     if (n >= 3) pool.push('archer', 'shade');
332:     if (n >= 4) pool.push('brute');
333:     if (n >= 5) pool.push('witch');
334:     if (n >= 7) pool.push('brute', 'witch');
335:     const isLast = run.wave === run.wavesTotal - 1;
336:     const eliteAllowed = n >= 4;
337:     let eliteBudget = isLast && (n === 4 || n === 7) ? 1 : 0;
338:     for (let i = 0; i < count; i++) {
339:       const type = pick(pool);
340:       const elite = eliteAllowed && (eliteBudget > 0 || (isLast && Math.random() < 0.13));
341:       if (elite) eliteBudget--;
342:       const pos = this.findSpawnPoint(300, 620);
343:       const delay = 0.24 * i + Math.random() * 0.18;
344:       this.spawnQueue.push({
345:         delay, type, x: pos.x, y: pos.y, elite,
346:         marker: 0.62,
347:       });
348:     }
349:     this.emit('hud');
350:   }
351: 
352:   findSpawnPoint(minD = 300, maxD = 620) {
353:     const p = this.player;
354:     for (let i = 0; i < 40; i++) {
355:       const a = Math.random() * TAU;
356:       const d = rnd(minD, maxD);
357:       const x = clamp(p.x + Math.cos(a) * d, MARGIN + 40, ROOM_W - MARGIN - 40);
358:       const y = clamp(p.y + Math.sin(a) * d, MARGIN + 40, ROOM_H - MARGIN - 40);
359:       if (this.obstacles.some((o) => dist(x, y, o.x, o.y) < o.r + 44)) continue;
360:       if (this.braziers.some((b) => dist(x, y, b.x, b.y) < 60)) continue;
361:       if (dist(x, y, p.x, p.y) < minD * 0.7) continue;
362:       return { x, y };
363:     }
364:     return { x: MARGIN + 200, y: MARGIN + 200 };
365:   }
