367:   // ============ rewards ============
368:   makeGates(n) {
369:     const run = this.run;
370:     const ownedHammers = new Set(run.hammers);
371:     const hammerAvail = (HAMMERS[run.weapon] || []).some((h) => !ownedHammers.has(h.id));
372:     const pool = ['boon', 'boon', 'heal', 'treasure', 'dark'];
373:     if (hammerAvail) pool.push('hammer');
374:     // guarantee hammer around the middle of the run
375:     const forceHammer = hammerAvail && (n === 3 || n === 6) && !run.hammers.length;
376:     let types = [];
377:     if (forceHammer) types.push('hammer');
378:     types.push('boon');
379:     const rest = shuffle(pool.filter((t) => !types.includes(t) || (t === 'boon' && types.filter((x) => x === 'boon').length < 1)));
380:     while (types.length < 3) {
381:       const t = rest.find((x) => !types.includes(x)) || pick(pool);
382:       if (!types.includes(t)) types.push(t);
383:     }
384:     types = shuffle(types);
385:     const godIds = shuffle(Object.keys(GODS));
386:     const usedGods = new Set();
387:     run.gates = types.map((type, i) => {
388:       if (type === 'boon') {
389:         let godId = godIds.find((g) => !usedGods.has(g)) || godIds[0];
390:         usedGods.add(godId);
391:         const god = GODS[godId];
392:         return {
393:           type, godId, title: `ДАР ${god.name.toUpperCase()}`, color: god.color,
394:           icon: god.symbol, name: god.name, desc: god.line, tag: 'БЛАГОСЛОВЕНИЕ',
395:         };
396:       }
397:       if (type === 'heal') return { type, title: 'ИСТОЧНИК КРОВИ', color: '#e0736b', icon: 'heart', desc: `Восстанови <b>35%</b> здоровья и иди дальше.`, tag: 'ЛЕЧЕНИЕ' };
398:       if (type === 'treasure') return { type, title: 'СУНДУК ХАРОНА', color: '#e3bd7b', icon: 'coin', desc: `Получи <b>90 оболов</b> для обновления даров.`, tag: 'БОГАТСТВО' };
399:       if (type === 'dark') return { type, title: 'СГУСТОК ТЬМЫ', color: '#b48bea', icon: 'moon', desc: `Получи <b>28 Тьмы</b> для Зеркала ночи.`, tag: 'ТЬМА' };
400:       return { type: 'hammer', title: 'МОЛОТ ДЕДАЛА', color: '#9fd8e8', icon: 'hammer', desc: `Улучши <b>${this.weapon.name}</b> навсегда до конца спуска.`, tag: 'КУЗНЯ' };
401:     });
402:     return run.gates;
403:   }
