405:   chooseGate(index) {
406:     const gate = this.run.gates[index];
407:     if (!gate) return;
408:     this.run.gates = [];
409:     this.audio.sfx('gate');
410:     if (gate.type === 'boon') {
411:       this.openBoon(gate.godId, false);
412:     } else if (gate.type === 'hammer') {
413:       this.openHammer();
414:     } else if (gate.type === 'heal') {
415:       const amount = Math.round(this.run.maxHp * 0.35);
416:       this.run.hp = Math.min(this.run.maxHp, this.run.hp + amount);
417:       this.float(this.player.x, this.player.y - 54, `+${amount}`, 'heal');
418:       this.toast('Кровь возвращается в жилы');
419:       this.audio.sfx('heal');
420:       this.nextChamber();
421:     } else if (gate.type === 'treasure') {
422:       this.run.obols += 90;
423:       this.toast('+90 оболов');
424:       this.audio.sfx('pickup');
425:       this.nextChamber();
426:     } else if (gate.type === 'dark') {
427:       this.run.darkEarned += 28;
428:       this.toast('+28 Тьмы');
429:       this.audio.sfx('pickup');
430:       this.nextChamber();
431:     }
432:   }
