434:   openBoon(godId, isReroll) {
435:     const run = this.run;
436:     let god = godId;
437:     let offers = this.rollBoonOffers(god);
438:     // if everything capped, switch to another god
439:     if (!offers.length) {
440:       const others = shuffle(Object.keys(GODS).filter((g) => g !== god));
441:       for (const g of others) {
442:         offers = this.rollBoonOffers(g);
443:         if (offers.length) { god = g; break; }
444:       }
445:     }
446:     this.pendingGod = god;
447:     this.pendingBoon = offers;
448:     if (!isReroll) run.rerolls = 0;
449:     const cost = 25 + run.rerolls * 15;
450:     this.emit('boon', {
451:       god: GODS[god], offers,
452:       rerollCost: cost, obols: run.obols,
453:       chamber: run.chamber,
454:     });
455:   }
456: 
457:   rollBoonOffers(godId) {
458:     const run = this.run;
459:     const defs = shuffle(BOONS.filter((b) => b.god === godId));
460:     const offers = [];
461:     for (const def of defs) {
462:       const owned = this.hasBoon(def.id);
463:       if (owned && owned.level >= MAX_BOON_LEVEL) continue;
464:       offers.push({
465:         def,
466:         rarity: this.rollRarity(),
467:         owned: owned || null,
468:       });
469:     }
470:     return offers.slice(0, 3);
471:   }
472: 
473:   rollRarity() {
474:     const n = this.run?.chamber || 1;
475:     const luck = Math.min(0.16, n * 0.015);
476:     const r = Math.random();
477:     if (r < 0.08 + luck) return 'epic';
478:     if (r < 0.38 + luck) return 'rare';
479:     return 'common';
480:   }
