482:   rerollBoons() {
483:     const run = this.run;
484:     const cost = 25 + run.rerolls * 15;
485:     if (run.obols < cost) { this.audio.sfx('hit'); return; }
486:     run.obols -= cost;
487:     run.rerolls++;
488:     this.openBoon(this.pendingGod, true);
489:     this.audio.sfx('pickup');
490:   }
