492:   takeBoon(index) {
493:     const offer = this.pendingBoon?.[index];
494:     if (!offer) return;
495:     const run = this.run;
496:     const existing = this.hasBoon(offer.def.id);
497:     if (existing) {
498:       existing.level = Math.min(MAX_BOON_LEVEL, existing.level + 1);
499:       existing.rarity = RARITY_ORDER_MAX(existing.rarity, offer.rarity);
500:     } else {
501:       run.boons.push({ id: offer.def.id, level: 1, rarity: offer.rarity });
502:     }
503:     this.recompute();
504:     const god = GODS[offer.def.god];
505:     this.toast(`${god.name}: ${offer.def.name}${existing ? ' · ур. ' + existing.level : ''}`);
506:     this.audio.sfx('boon');
507:     this.pendingBoon = null;
508:     this.emit('hud');
509:     this.nextChamber();
510:   }
