512:   openHammer() {
513:     const run = this.run;
514:     const owned = new Set(run.hammers);
515:     const pool = (HAMMERS[run.weapon] || []).filter((h) => !owned.has(h.id));
516:     if (!pool.length) {
517:       this.run.obols += 60;
518:       this.toast('Кузня пуста · +60 оболов');
519:       this.nextChamber();
520:       return;
