600:       darkGain: darkGain ?? Math.round(run.darkEarned * (1 + (run.meta.greed || 0) * 0.3)),
601:       boons: run.boons.map((b) => ({ ...BOON_BY_ID.get(b.id), ...b })),
602:       hammers: run.hammers.map((id) => (HAMMERS[run.weapon] || []).find((h) => h.id === id)).filter(Boolean),
603:       weapon: this.weapon,
