608:   die() {
609:     if (this.state === 'dying' || this.state === 'victory' || this.state === 'dead') return;
610:     const run = this.run;
611:     if ((run.meta.revive || 0) > 0 && !run.reviveUsed) {
612:       run.reviveUsed = true;
613:       run.hp = Math.round(run.maxHp * 0.45);
614:       this.player.invuln = 2.4;
615:       this.audio.sfx('rage');
616:       this.shake(14);
