162: function updateHud(force = false) {
163:   if (!game || !game.run) return;
164:   const h = game.getHud();
165:   if (!h) return;
166: 
167:   UI.biome.textContent = h.biome;
168:   UI.chamber.textContent = `ЗАЛ ${roman(h.chamber)}`;
169: 
170:   const hpFrac = h.maxHp > 0 ? clamp(h.hp / h.maxHp, 0, 1) : 0;
171:   UI.hpText.textContent = `${h.hp} / ${h.maxHp}`;
172:   UI.hpFill.style.width = `${hpFrac * 100}%`;
173:   UI.hpFill.classList.toggle('low', hpFrac < 0.3);
174:   UI.hpShield.classList.toggle('hidden', !h.shield);
175:   UI.obols.textContent = String(h.obols);
176:   UI.dark.textContent = String(h.dark);
177: 
178:   const sig = h.boons.map((b) => `${b.id}:${b.level}:${b.rarity}`).join('|');
179:   if (force || sig !== lastBoonSig) {
180:     lastBoonSig = sig;
181:     UI.boons.innerHTML = h.boons.map((b) => {
182:       const god = GODS[b.god] || GODS.zeus;
183:       return `<span class="boon-chip" style="--c:${god.color}" title="${esc(b.name)} — ${esc(god.name)}">
184:         ${icon(b.icon)}<span class="lvl">${b.level}</span>
185:       </span>`;
186:     }).join('');
187:   }
188: 
189:   const dashCooling = h.dashCharges <= 0;
190:   UI.dashAbility.classList.toggle('cooling', dashCooling);
191:   UI.dashAbility.classList.toggle('ready', !dashCooling);
192:   UI.chargesDash.textContent = h.dashMax > 1 ? String(h.dashCharges) : '';
193: 
194:   const specialCooling = h.specialFrac < 0.995;
195:   UI.specialAbility.classList.toggle('cooling', specialCooling);
196:   UI.specialAbility.classList.toggle('ready', !specialCooling);
197: 
198:   const rageReady = h.rage >= h.rageMax;
199:   UI.rageAbility.classList.toggle('ready', rageReady);
200:   UI.rageFill.style.height = `${clamp((h.rage / h.rageMax) * 100, 0, 100)}%`;
201: 
202:   if (h.boss) {
203:     UI.bossBar.classList.remove('hidden');
204:     UI.bossName.textContent = h.boss.name;
205:     UI.bossTag.textContent = h.boss.tag;
206:     UI.bossFill.style.width = `${clamp((h.boss.hp / h.boss.max) * 100, 0, 100)}%`;
207:   } else {
208:     UI.bossBar.classList.add('hidden');
209:   }
210: 
211:   lastHudAt = performance.now();
212: }
