217: function mirrorRow(upgrade, compact = false) {
218:   const level = save.meta[upgrade.id] || 0;
219:   const maxed = level >= upgrade.max;
220:   const cost = maxed ? 0 : upgrade.cost(level);
221:   const affordable = save.darkness >= cost;
222:   let pipsHtml = '<span class="pips">';
223:   for (let i = 0; i < upgrade.max; i++) pipsHtml += `<span class="pip ${i < level ? 'on' : ''}"></span>`;
224:   pipsHtml += '</span>';
225: 
226:   const buy = maxed
227:     ? '<button class="up-buy maxed" disabled>МАКС</button>'
228:     : `<button class="up-buy" data-buy="${upgrade.id}" ${affordable ? '' : 'disabled'} title="Стоимость: ${cost} Тьмы">
229:          <span class="mini-gem"></span>${cost}
230:        </button>`;
231: 
232:   return `
233:     <div class="up-row" data-upgrade="${upgrade.id}">
234:       <div class="up-icon">${icon(upgrade.icon)}</div>
235:       <div class="up-body">
236:         <div class="up-name">${esc(upgrade.name)}${pipsHtml}</div>
237:         <div class="up-desc">${esc(upgrade.desc)}${compact ? '' : ''}</div>
238:       </div>
239:       ${buy}
240:     </div>`;
