261: function buyMeta(id) {
262:   const upgrade = META_UPGRADES.find((u) => u.id === id);
263:   if (!upgrade) return;
264:   const level = save.meta[id] || 0;
265:   if (level >= upgrade.max) return;
266:   const cost = upgrade.cost(level);
267:   if (save.darkness < cost) return;
268:   audio.init();
