270:   save.darkness -= cost;
271:   save.meta[id] = level + 1;
272:   writeSave(save);
273:   updateHub();
274:   if (overlayKind === 'mirror') openMirrorSheet(true);
275:   showToast(`${upgrade.name} · уровень ${level + 1}`);
