376: function recordRun(summary, victory) {
377:   const dark = Math.max(0, Math.round(summary.darkGain || 0));
378:   save.darkness += dark;
379:   save.runs = (save.runs || 0) + 1;
380:   save.totalKills = (save.totalKills || 0) + (summary.kills || 0);
381:   save.bestChamber = Math.max(save.bestChamber || 0, summary.chamber || 0);
382:   if (victory) {
383:     save.wins = (save.wins || 0) + 1;
384:     const t = Math.round(summary.time || 0);
385:     if (!save.bestTime || t < save.bestTime) save.bestTime = t;
386:   }
387:   writeSave(save);
388:   updateHub();
389:   return dark;
390: }
