396:   }).join('');
397:   const hammers = (summary.hammers || []).map((h) => (
398:     `<span class="boon-chip" style="--c:#9fd8e8" title="${esc(h.name)}">${icon(h.icon)}</span>`
399:   )).join('');
400:   return boons + hammers;
