545: function abandonRun() {
546:   if (!game || !game.run) return;
547:   const greed = 1 + ((game.run.meta && game.run.meta.greed) || 0) * 0.3;
548:   const dark = Math.round((game.run.darkEarned || 0) * greed);
549:   save.darkness += dark;
550:   save.runs = (save.runs || 0) + 1;
551:   save.totalKills = (save.totalKills || 0) + (game.run.kills || 0);
552:   save.bestChamber = Math.max(save.bestChamber || 0, game.run.chamber || 0);
553:   writeSave(save);
554:   returnHome(`Спуск прерван · +${dark} Тьмы`);
555: }
