579: UI.overlay.addEventListener('click', (e) => {
580:   const target = e.target.closest('button, [data-action]');
581:   if (!target || !UI.overlay.contains(target)) return;
582: 
583:   const buy = target.closest('[data-buy]');
584:   if (buy) { buyMeta(buy.dataset.buy); return; }
